export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        {analytics ? (
          <>
            <p>Views: {analytics.views}</p>
            <p>Visitors: {analytics.visitors}</p>
            <p>Bounce rate: {analytics.bounceRate}%</p>
          </>
        ) : (
          <p>Analytics data unavailable</p>
        )}
      </section>

      <section>
        <h3>Notifications</h3>
        {notifications.length > 0 ? (
          <ul>
            {notifications.map((n) => (
              <li key={n.id}>
                {n.message} — {n.date}
              </li>
            ))}
          </ul>
        ) : (
          <p>No new notifications</p>
        )}
      </section>

      <section>
        <h3>Settings</h3>
        {settings ? (
          <>
            <p>Theme: {settings.theme}</p>
            <p>Language: {settings.language}</p>
            <p>Notifications enabled: {settings.notificationsEnabled ? 'Yes' : 'No'}</p>
          </>
        ) : (
          <p>Settings unavailable</p>
        )}
      </section>
    </div>
  )
}

async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then((r) => r.json()),
      fetch('/api/notifications').then((r) => r.json()),
      fetch('/api/settings').then((r) => r.json()),
    ])

    return { analytics, notifications, settings }
  } catch {
    return {
      analytics: {
        views: 1500,
        visitors: 423,
        bounceRate: 34,
      },
      notifications: [
        { id: 1, message: 'New sign-up', date: '2026-08-04' },
        { id: 2, message: 'Payment received', date: '2026-08-03' },
      ],
      settings: {
        theme: 'light',
        language: 'en',
        notificationsEnabled: true,
      },
    }
  }
}

